'use strict';
const view=document.getElementById('view');
const icons={rules:'<rect x="5" y="3" width="15" height="20" rx="2"/><path d="M9 8h7M9 12h7M9 16h4"/>',hub:'<circle cx="12" cy="12" r="4"/><circle cx="3" cy="4" r="2"/><circle cx="21" cy="4" r="2"/><circle cx="3" cy="21" r="2"/><circle cx="21" cy="21" r="2"/><path d="m5 6 4 4m6 0 4-4M5 19l4-4m6 0 4 4"/>',states:'<path d="m3 8 9-5 9 5M4 21h16M6 10v8m6-8v8m6-8v8M3 8h18"/>'};
const icon=k=>`<svg viewBox="0 0 24 26" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]}</svg>`;
const steps=[['house','01','rules','Prepare rules & people','START NOW','Open the model House rules. Recruit the team. Senate offices use their own rules.',['Rules package','Hiring','Readiness']],['hub','02','hub','Connect the committee spokes','ORGANIZE','A shared professional hub supports each committee’s authorized work.',['Legal hub','House + Senate','Evidence controls']],['states','03','states','Review lawful referrals','COORDINATE','Share only what the law permits. Independent prosecutors decide what follows.',['State nexus','Referral standards','Independent review']]];
const sets={
rules:[['authority','Codify staff-led depositions','Existing counsel-led authority is the starting point. Put durable procedures in the proposed rules package; preserve witness rights.','Appendix A · §2','templates/appendix-a-house-rules.md'],['exigency','Define a narrow emergency process','Document specific urgency and distinguish notice from consultation. Preserve minority participation and a reviewable decision.','Appendix A · §2','templates/appendix-a-house-rules.md'],['sharing','Set lawful sharing boundaries','Use a shared catalog with separate tax, SAR, confidential and court-restricted compartments. House rules cannot override statutory secrecy.','Authority chapter · §§3–5','01-hub-and-authorities.html'],['enforcement','Prepare enforcement authorization','Draft prospective House authorization and the OGC file. Court jurisdiction, standing and remedies remain case-specific questions.','Appendix A · §5','templates/appendix-a-house-rules.md'],['adoption','Obtain parliamentary and counsel review','Confirm the adopted 120th rules, committee organization, jurisdiction and delegations before issuing process. January 6 is a conditional target.','Readiness chapter · §6','04-jan6-and-readiness.html']],
hiring:[['leaders','Recruit the leadership team','Prioritize a staff director, chief investigative counsel and legislative counsel. Record conflicts, reporting lines and appointment authority.','Staffing matrix · §7','04-jan6-and-readiness.html'],['forensics','Build financial and technical capacity','Recruit forensic accounting, financial intelligence and data engineering expertise against defined tasks and lawful access needs.','Staffing matrix · §7','04-jan6-and-readiness.html'],['custody','Appoint evidence and privacy owners','Assign records custody, information security, statutory-access review and witness/privacy counsel before sensitive collection.','Authority chapter · §3','01-hub-and-authorities.html'],['review','Reserve independent review capacity','Separate collection, verification and release. Former government employment does not transfer clearances, records or investigative powers.','Onboarding · §8','04-jan6-and-readiness.html']],
readiness:[['charter','Agree the joint investigative charter','Define legislative questions, committee owners, decision rights, resources and lawful access. Each compulsory request needs actual authority.','Authority chapter · §1','01-hub-and-authorities.html'],['requests','Prepare scoped requests now','Develop purposes, document categories and preservation requests. Authorized officials issue and serve any later subpoenas.','Appendices B and C','templates/appendix-b-legislative-purpose.md'],['systems','Approve systems before collection','The public PWA is a playbook, not a restricted government evidence vault. Protect metadata, derivatives and exports as well as originals.','Forensics · §5','03-financial-forensics.html'],['calendar','Use the transition readiness plan','The model runs November 7–January 5, with launch dependent on actual organization and authority. It is a proposed plan, not the House calendar.','Weekly plan · §9','04-jan6-and-readiness.html']],
hub:[['service','Establish a shared professional service','Coordinate counsel, financial analysis, evidence custody and verification. Retain the actual powers and responsibilities of each issuing committee.','Hub charter · §1','01-hub-and-authorities.html'],['nodes','Connect the committee spokes','Oversight, Judiciary, Financial Services and Ways and Means lead within their jurisdictions. Senate participation requires separate authority.','Committee nodes','01-hub-and-authorities.html'],['facts','Develop facts before public presentation','Use rights-respecting staff examinations, transcript review, source checks and evidence-led hearings. Keep counterevidence visible.','January 6 lessons · §§4–5','04-jan6-and-readiness.html'],['handoffs','Review lawful referrals as evidence develops','A timely handoff still requires item-by-item disclosure and independent-source review. Protected records do not become generally shareable.','State workflow · §4','02-state-referrals.html']],
states:[['nexus','Establish the actual state nexus','Match conduct to territorial jurisdiction and statutory elements. A clearing bank or registered agent is not a universal shortcut.','State matrix · §2','02-state-referrals.html'],['dossier','Prepare a lawful referral dossier','Include an evidence index, custody, authentication, counterevidence and a disclosure decision for each item.','Appendix D','templates/appendix-d-state-referral.md'],['independence','Keep state decisions independent','The receiving office decides whether and how to proceed and obtains necessary evidence. Congress does not direct charging or witness cooperation.','State workflow · §§4–5','02-state-referrals.html'],['limits','Check immunity and use restrictions','Review official-act immunity, grand-jury secrecy, tax/SAR controls, double jeopardy and preemption. D.C. needs a distinct analysis.','Constitutional limits · §3','02-state-referrals.html']]
};
const heading=(k,h,p)=>`<div class="section-heading"><p class="eyebrow">${k}</p><h1>${h}</h1><p class="lede">${p}</p></div>`;
const resourceMap={
 'rules-authority':['Staff-deposition rules','templates/appendix-a-house-rules.md'],
 'rules-exigency':['Emergency notice and consultation clause','templates/appendix-a-house-rules.md'],
 'rules-sharing':['Evidence-sharing safeguards','docs/01-hub-and-authorities.md'],
 'rules-enforcement':['Civil-enforcement authorization','templates/appendix-a-house-rules.md'],
 'rules-adoption':['Rules and staffing review briefing','templates/house-office-briefing.md'],
 'hiring-leaders':['Leadership recruitment plan','templates/staffing-and-recruitment-plan.md'],
 'hiring-forensics':['Financial and technical staffing plan','templates/staffing-and-recruitment-plan.md'],
 'hiring-custody':['Evidence and privacy staffing plan','templates/staffing-and-recruitment-plan.md'],
 'hiring-review':['Independent-review staffing plan','templates/staffing-and-recruitment-plan.md'],
 'readiness-charter':['Central Hub operating charter','templates/central-hub-charter.md'],
 'readiness-requests':['Legislative-purpose memorandum','templates/appendix-b-legislative-purpose.md'],
 'readiness-systems':['Evidence systems and access protocol','docs/01-hub-and-authorities.md'],
 'readiness-calendar':['Transition readiness schedule','docs/04-jan6-and-readiness.md'],
 'hub-service':['Central Hub operating charter','templates/central-hub-charter.md'],
 'hub-nodes':['Committee-node operating mandates','templates/committee-node-operating-plan.md'],
 'hub-facts':['Deposition and hearing procedures','docs/04-jan6-and-readiness.md'],
 'hub-handoffs':['State referral transmittal package','templates/appendix-d-state-referral.md'],
 'states-nexus':['State jurisdiction and statutory matrix','docs/02-state-referrals.md'],
 'states-dossier':['State referral transmittal package','templates/appendix-d-state-referral.md'],
 'states-independence':['Independent-enforcement coordination plan','docs/02-state-referrals.md'],
 'states-limits':['Constitutional and disclosure safeguards','docs/05-litigation-and-privilege.md']
};
function tasks(key){return `<div class="document-status-note"><strong>Our drafts are prepared.</strong> Open the document, suggest edits or make your own copy. Google Docs sharing applies. Official adoption, appointments and legal review are separate actions.</div><div class="task-list">${sets[key].map(([id,h,p,source,url])=>{const r=resourceMap[key+'-'+id];return `<article class="task document-task"><div class="document-icon" aria-hidden="true">▤</div><div><h3>${r[0]}</h3><p>${p}</p><span class="source-context">${source}</span><div class="doc-actions" data-document="${r[1]}"></div></div><span class="draft-label">DRAFT CREATED</span></article>`;}).join('')}</div>`;}
function wheel(){return `<section class="wheel-panel" aria-labelledby="wheel-title"><div class="wheel-heading"><h2 id="wheel-title">One hub. Separate powers.</h2><p>Choose a spoke to see its role and documents.</p></div><svg class="oversight-wheel" viewBox="0 0 760 420" aria-labelledby="wheel-svg-title wheel-svg-desc"><title id="wheel-svg-title">The proposed House, Senate and state oversight network</title><desc id="wheel-svg-desc">House and Senate committees keep their own authority. A shared legal and forensic hub supports their work. A separate dotted referral line connects to independent state attorneys general and district attorneys.</desc><circle class="wheel-ring" cx="380" cy="203" r="156"/><path class="wheel-spoke" d="M380 203 160 98M380 203 600 98"/><path class="wheel-referral" d="M380 244V334"/><text class="wheel-edge-label" x="380" y="298" text-anchor="middle">lawful referral · no command</text><a href="#house" aria-label="Explore House committees and model rules"><rect class="wheel-node" x="25" y="38" width="270" height="116" rx="12"/><text class="wheel-label" x="160" y="72" text-anchor="middle">HOUSE COMMITTEES</text><text class="wheel-small" x="160" y="99" text-anchor="middle">Oversight · Judiciary</text><text class="wheel-small" x="160" y="122" text-anchor="middle">Financial Services · Ways and Means</text></a><a href="#senate" aria-label="Explore Senate investigative authority"><rect class="wheel-node" x="465" y="38" width="270" height="116" rx="12"/><text class="wheel-label" x="600" y="72" text-anchor="middle">SENATE COMMITTEES</text><text class="wheel-small" x="600" y="99" text-anchor="middle">HSGAC / PSI · Judiciary</text><text class="wheel-small" x="600" y="122" text-anchor="middle">Banking · Finance</text></a><a href="#hub" aria-label="Explore the shared legal and forensic hub"><rect class="wheel-center" x="240" y="169" width="280" height="87" rx="16"/><text class="wheel-center-label" x="380" y="201" text-anchor="middle">SHARED PROFESSIONAL HUB</text><text class="wheel-center-small" x="380" y="228" text-anchor="middle">Legal · Forensics · Evidence · Review</text></a><a href="#states" aria-label="Explore independent state enforcement and referral review"><rect class="wheel-node state-node" x="235" y="334" width="290" height="70" rx="12"/><text class="wheel-label" x="380" y="362" text-anchor="middle">INDEPENDENT STATE AGs / DAs</text><text class="wheel-small" x="380" y="385" text-anchor="middle">They decide jurisdiction and enforcement.</text></a></svg><svg class="oversight-wheel-mobile" viewBox="0 0 340 350" aria-labelledby="mobile-wheel-title"><title id="mobile-wheel-title">House and Senate committees connect to a shared hub; lawful referrals go to independent states.</title><circle class="wheel-ring" cx="170" cy="160" r="118"/><path class="wheel-spoke" d="M170 160 80 54M170 160 260 54"/><path class="wheel-referral" d="M170 194V282"/><text class="wheel-edge-label" x="170" y="236" text-anchor="middle">lawful referral</text><text class="wheel-edge-label" x="170" y="254" text-anchor="middle">no command</text><a href="#house" aria-label="Explore House committees and rules"><rect class="wheel-node" x="8" y="19" width="144" height="68" rx="10"/><text class="wheel-label" x="80" y="47" text-anchor="middle">HOUSE</text><text class="wheel-small" x="80" y="68" text-anchor="middle">Committee spokes</text></a><a href="#senate" aria-label="Explore Senate committees and powers"><rect class="wheel-node" x="188" y="19" width="144" height="68" rx="10"/><text class="wheel-label" x="260" y="47" text-anchor="middle">SENATE</text><text class="wheel-small" x="260" y="68" text-anchor="middle">Committee spokes</text></a><a href="#hub" aria-label="Explore the shared legal and forensic hub"><rect class="wheel-center" x="43" y="126" width="254" height="68" rx="12"/><text class="wheel-center-label" x="170" y="153" text-anchor="middle">SHARED PROFESSIONAL HUB</text><text class="wheel-center-small" x="170" y="176" text-anchor="middle">Legal · Forensics · Evidence · Review</text></a><a href="#states" aria-label="Explore independent state referrals"><rect class="wheel-node" x="27" y="282" width="286" height="60" rx="10"/><text class="wheel-label" x="170" y="307" text-anchor="middle">INDEPENDENT STATE AGs / DAs</text><text class="wheel-small" x="170" y="328" text-anchor="middle">They decide enforcement.</text></a></svg><div class="wheel-text-links" aria-label="Explore each part"><a href="#house">House rules →</a><a href="#senate">Senate powers →</a><a href="#hub">Shared hub →</a><a href="#states">State referrals →</a></div><p class="wheel-caption">Proposed coordination, not a new chain of command. Each committee keeps its legal authority; protected records stay compartmented.</p></section>`;}
function home(){return `<section class="landing-hero"><div class="member-intro"><p class="eyebrow"><span class="tiny-line"></span>FOR HOUSE & SENATE OFFICES · PREPARE NOW</p><h1>Prepare the team.<br><em>Connect the oversight.</em></h1><p class="hero-copy">A practical three-step plan. Start with rules and hiring, then follow the documents as deeply as needed.</p><div class="hero-actions"><a class="primary-button" href="#house">Review the House package <span aria-hidden="true">↗</span></a><a class="hero-secondary" href="#library">Explore the playbook <span aria-hidden="true">→</span></a></div><div class="hero-principle"><span class="principle-mark" aria-hidden="true">◇</span><p>Prepared drafts.<br><strong>Independent judgment.</strong></p></div></div><div class="hero-blueprint">${wheel()}</div><div class="hero-footnote"><span>INDEPENDENT CIVIC PROJECT</span><span>Working drafts · Human review required</span></div></section><section class="path-section"><div class="section-line"><div><p class="eyebrow">THE PATH FORWARD</p><h2>Three steps. One practical starting point.</h2></div><span>CHOOSE YOUR NEXT STEP ↘</span></div><div class="step-grid">${steps.map(([id,n,i,h,t,p,tags])=>`<a class="step-card ${id}" href="#${id}"><div class="card-top"><span class="step-number">${n}</span><span class="step-timing">${t}</span></div><div class="step-icon">${icon(i)}</div><h2>${h} <span>↗</span></h2><p>${p}</p><div class="tag-line">${tags.map(t=>`<span>${t}</span>`).join('')}</div></a>`).join('')}</div><div class="start-resources"><span>QUICK ACCESS</span><a href="#hiring">Hiring plan ↗</a><a href="#library">Prepared documents ↗</a><a href="#senate">For Senate offices ↗</a></div></section><section class="explore-invitation"><div class="invitation-mark" aria-hidden="true">?</div><div><p class="eyebrow">EXPLORE THE QUESTIONS</p><h2>What should Congress examine?</h2><p>Browse source-backed oversight topics, what is known and what still needs checking.</p></div><a class="primary-button" href="#topics">Explore investigation topics <span aria-hidden="true">↗</span></a></section><details class="lesson-panel"><summary>How are the documents checked?</summary><p>Drafts, source checks, independent agent review and human legal review are different stages. Open the audit record to see the scope, findings and unresolved limits.</p><a href="#assurance">Read the audit and review record →</a></details><div class="bottom-note"><span class="note-mark">i</span><p><strong>Prepared drafts, not adopted authority.</strong> This independent prototype runs no official investigation or confidential tip intake.</p><a href="#roadmap">What is built? →</a></div>`;}
function senate(){return heading('SENATE OFFICES · SEPARATE AUTHORITY','Yes. The Senate investigates too.','Senate committees conduct legislative oversight within their jurisdictions. Their own Senate and committee rules govern hearings, subpoenas and staff practice—not the model House resolution.')+`<div class="senate-summary"><strong>The same shared-support idea. A separate authorization path.</strong><p>The hub can support coordinated research and lawful exchanges. It cannot lend one chamber’s compulsory powers to another, grant access to restricted records or direct a state prosecutor.</p></div><div class="senate-actions"><details class="lesson-panel" open><summary>1. Choose the Senate committee</summary><p>Homeland Security and Governmental Affairs and its Permanent Subcommittee on Investigations examine matters within their authorized scope. Judiciary, Banking and Finance supply subject-matter pathways. Assign the question to the proper committee and document its legislative purpose.</p><a href="01-hub-and-authorities.html">Read committee jurisdiction and Senate integration →</a></details><details class="lesson-panel"><summary>2. Confirm the actual rules and approvals</summary><p>Read Senate Rule XXVI, the jurisdictional provisions of Rule XXV, and the responsible committee’s current rules and authorizing instruments. Confirm who can authorize and sign a subpoena, consultation or vote requirements, witness rights and the rules applicable to any staff examination before issuing process.</p><p>A draft for the 120th House is not Senate authority. A staff support agreement does not eliminate these requirements.</p><a href="https://www.rules.senate.gov/rules-of-the-senate">Read the official Standing Rules of the Senate →</a></details><details class="lesson-panel"><summary>3. Connect research without merging legal powers</summary><p>Name the Senate custodian and authorized reviewers. Record the legal basis for each exchange, protect source restrictions and preserve independent decisions. Finance Committee tax-access provisions require their own statutory review; other committees do not inherit that access.</p><div class="doc-actions" data-document="templates/committee-node-operating-plan.md"></div></details></div><div class="next-step"><div><span>SHARED SUPPORT</span><h2>See how the hub serves each committee.</h2></div><a class="primary-button" href="#hub">Explore the hub →</a></div>`;}
function house(tab='rules'){if(!['rules','hiring','readiness'].includes(tab))tab='rules';return `<div class="breadcrumb"><a href="#home">The path forward</a> / Step 1</div>${heading('STEP 01 · START NOW','Prepare the House.','Our model rules, hiring plan and readiness documents are already drafted. Open the resources below to review, copy and adapt them.')}<div class="stage-banner"><span class="badge amber">DRAFT PACKAGE READY</span><p>Drafted by our project. House adoption, funding and appointments remain decisions for authorized offices.</p><a class="download-link" href="templates/appendix-a-house-rules.md">Model rules package →</a></div><div class="tabs" role="tablist" aria-label="House readiness">${['rules','hiring','readiness'].map(t=>`<a role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" href="#house/${t}">${({rules:'House rules',hiring:'Hiring & people',readiness:'Readiness checklist'})[t]}</a>`).join('')}</div>${tasks(tab)}<div class="next-step"><div><span>THEN</span><h2>Give the team a shared hub.</h2></div><a class="primary-button" href="#hub">Step 2 · Build the hub →</a></div>`;}
function hiring(){return heading('STEP 01 · PEOPLE AND CAPACITY','Hire for the work ahead.','A proposed 24-seat complement, sequenced around leadership, evidence custody and independent review. Actual appointments, funding and clearances belong to the responsible offices.')+`<div class="role-grid">${[['Leadership','Staff director · Chief investigative counsel · Legislative counsel','FIRST'],['Financial analysis','Forensic accounting · Financial intelligence · Data engineering','BUILD'],['Evidence & protection','Records officer · Security · Privacy and statutory-access counsel','BEFORE COLLECTION'],['Independent review','Verification editor · Review counsel · State-referral counsel','RESERVE CAPACITY']].map(([h,p,b])=>`<article class="role-card"><span class="badge">${b}</span><h2>${h}</h2><p>${p}</p></article>`).join('')}</div>`+tasks('hiring')+`<div class="source-callout"><strong>Recruitment is already underway in existing offices.</strong><p>Observed November 6: Judiciary Committee Democratic staff is recruiting for the 120th Congress, including oversight/investigations counsel or professional staff. This does not establish hiring by Raskin’s personal office or approval of this proposed hub. The official page controls current openings.</p><a href="https://democrats-judiciary.house.gov/about/job-opportunities">Official committee job opportunities →</a> · <a href="04-jan6-and-readiness.html">Our staffing and clearance matrix →</a></div>`;}
function hub(){return heading('STEP 02 · ORGANIZE','One hub. House and Senate spokes.','Share professional capacity and a common evidence catalog. Keep issuing authority, statutory access and release decisions with their lawful owners.')+wheel()+tasks('hub')+`<details class="lesson-panel"><summary>What we change after the January 6 investigation <span>＋</span></summary><p>Preserve specialist teams, disciplined staff examinations and clear public explanation. Prepare scoped third-party requests early, use standing committee jurisdiction, and review lawful referrals throughout the inquiry. Sharing and timing involved documented investigative tradeoffs, not simply a lack of authority.</p><a href="04-jan6-and-readiness.html">Read the sourced lessons →</a></details><div class="next-step"><div><span>THEN</span><h2>Connect lawful state pathways.</h2></div><a class="primary-button" href="#states">Step 3 · State enforcement →</a></div>`;}
function states(){return heading('STEP 03 · COORDINATE','Connect state enforcement.','A lawful evidentiary bridge to independent state attorneys general and district attorneys. The receiving office decides what follows.')+`<div class="state-grid">${[['NY','New York','Securities, persistent fraud and enterprise-corruption analysis. Actual nexus and elements are required.'],['DE','Delaware','Corporate or LLC remedies under the applicable statute. Formation alone does not establish wrongdoing.'],['CA','California','Unfair practices, securities and financial-services rules, with their jurisdictional limits.'],['+','Other jurisdictions','FL · NJ · VA · NV · IL, plus a distinct D.C. analysis. Use the full statutory matrix.']].map(([s,h,p])=>`<a class="state-card" href="02-state-referrals.html"><span>${s}</span><h2>${h} →</h2><p>${p}</p></a>`).join('')}</div>`+tasks('states')+`<div class="source-callout"><strong>Independent enforcement. Qualified claims.</strong><p>Jurisdiction is not automatic. Immunity, admissibility, preemption and disclosure limits survive a referral. D.C. requires separate clemency analysis. No AG connection or real-time referral service operates in this prototype.</p><a href="templates/appendix-d-state-referral.md">Referral dossier model →</a></div>`;}
function roadmap(){return heading('BUILD STATUS · 7 NOVEMBER 2026','From blueprint to working system.','Three steps describe the institutional plan. These milestones describe our product’s delivery and verification gates.')+`<div class="maturity-grid">${[['done','PROOF OF CONCEPT','Architecture & contracts','Researched manual, Appendices A–G, 33 skills, packet schema and local validation tools.','SOURCE ARTIFACTS BUILT'],['current','PROTOTYPE · CURRENT','House + Senate PWA','Three-step navigation, prepared rules and hiring documents, Google Docs links, playbook search and an offline shell.','INTERACTIVE DEMONSTRATION'],['','MINIMUM VIABLE PRODUCT','One maintained workflow','Protected public repository, verified human reviewers, one public-source task and a completed correction exercise.','NEXT DELIVERY GATE']].map(([c,b,h,p,s])=>`<article class="maturity ${c}"><span class="badge ${c==='current'?'amber':''}">${b}</span><h2>${h}</h2><p>${p}</p><span class="state-text">${s}</span></article>`).join('')}</div><div class="roadmap-list">${[['P0','House-office review packet','A concise rules/hiring briefing, authority review and representative-specific outreach preparation. No outreach sent.'],['P0','Public GitHub and governance','Create the independent repository; configure protections, reviewer identities and release controls. Creation access remains required.'],['P0','Controlled research pilot','One bounded public-source question, contrary evidence, source checks and independent human legal/privacy review.'],['P1','Confidential reporting','A separately operated source-protection platform, counsel, trained handlers and independent security review. No sensitive form before that gate.'],['P1','Agent-network service','Implement task leases, signed submission/audit APIs, primary-source verification, scope controls and stop mechanisms.'],['P2','Runtime and community adapters','Qualify OpenClaw, MCP and A2A adapters. Optional Moltbook discovery follows a working review pipeline. No unattended swarm is active.']].map(([p,h,d])=>`<article><span class="priority">${p}</span><div><h3>${h}</h3><p>${d}</p></div><span class="roadmap-status">PLANNED</span></article>`).join('')}</div><a href="ROADMAP.md" class="primary-button">Download the complete roadmap →</a>`;}
let chapters=[],chapterState='loading';
function library(){return heading('READY-TO-USE WORKING DRAFTS','The document library.','The rules package, staffing plan, hub charter, committee mandates and referral materials are already created. Read here, open Google Docs or download the source.')+`<div class="collaboration-note"><strong>Google Docs for collaboration.</strong><p>Use Suggesting to propose edits, or File → Make a copy to adapt a document. Approved editors can edit directly. Google Drive permissions still apply; links do not automatically grant public access.</p><a href="https://docs.google.com/document/d/19plHMuNSrSzeXsPf8YLhF7kWHf_QNJKwFhYlR1pmrgQ/edit?usp=drivesdk" target="_blank" rel="noopener noreferrer">Open the Google Docs index →</a></div><div class="library-search"><label for="chapter-search">Find a document or topic</label><input id="chapter-search" type="search" placeholder="Try rules, hiring, charter, state or evidence" autocomplete="off"></div><div class="chapter-list" id="chapter-results"></div><p class="local-note">Draft created means our document exists. It does not mean a House rule has been adopted, an office has hired staff, or an agency has approved a referral.</p>`;}
function search(query=''){
 const box=document.getElementById('chapter-results');if(!box)return;box.replaceChildren();
 const catalog=window.oversightDocs?.items||[];
 const records=catalog.length?catalog.map(d=>({...d,text:(chapters.find(c=>c.path===d.path||c.url===d.read_url)||{}).text||''})):chapters.map(c=>({title:c.title,path:c.path,read_url:c.url,text:c.text}));
 const found=records.filter(c=>(c.title+' '+c.path+' '+c.text).toLowerCase().includes(query.toLowerCase()));
 for(const d of found){const row=document.createElement('article');row.className='library-document';const top=document.createElement('div');top.className='library-document-title';const h=document.createElement('h3');h.textContent=d.title;const badge=document.createElement('span');badge.className='draft-label';badge.textContent='DRAFT CREATED';top.append(h,badge);row.append(top);if(d.path){const actions=document.createElement('div');actions.className='doc-actions';actions.dataset.document=d.path;row.append(actions);}else{const a=document.createElement('a');a.href=d.read_url;a.textContent='Read draft →';row.append(a);}box.append(row);}
 if(!found.length)box.textContent=chapterState==='error'?'Document index unavailable. Use the Google Docs index above.':chapterState==='loaded'?'No matching document.':'Loading the document library…';
 window.oversightDocs?.hydrate();
}
function contribute(){return heading('PUBLIC RESEARCH · PROTECTED SOURCES','Choose the right channel.','Public research and confidential disclosures need different handling. No sensitive intake or autonomous investigation is activated here.')+`<div class="contribute-grid"><article class="contribute-card"><span class="badge">PUBLIC RESEARCH</span><h2>Help verify the record.</h2><p>Contribute public filings, citations, alternative explanations and corrections. Use the packet standard and independent review workflow.</p><a class="primary-button" href="CONTRIBUTING.md">Contribution standards →</a></article><article class="contribute-card secure"><span class="badge amber">CONFIDENTIAL REPORTING · NOT OPEN</span><h2>Protect the source first.</h2><p>Do not upload private financial records, tax returns, SARs, sealed files or identifying details here. This PWA cannot promise anonymity.</p><button class="primary-button" data-action="reporting">View secure-intake plan →</button></article></div><section class="agent-plan"><div>${icon('hub')}</div><div><p class="eyebrow">AUTONOMOUS RESEARCH · ROADMAP</p><h2>Agents gather. Auditors challenge. Humans decide.</h2><p>Future workers use public sources and scoped tasks. Three independent audits may route a packet to human review. They cannot authorize publication, official referrals or restricted-vault access.</p><a href="10-autonomous-network.html">Read Appendix G →</a></div></section>`;}
function modal(text){document.getElementById('dialog-content').innerHTML=text;document.getElementById('info-dialog').showModal();}
function route(){const [id='home',tab]=(location.hash.slice(1)||'home').split('/');const pages={home,house:()=>house(tab),senate,hiring,hub,states,library,roadmap,contribute,...(window.oversightExplore?.pages||{})};view.innerHTML=(Object.hasOwn(pages,id)&&typeof pages[id]==='function'?pages[id]:home)();window.oversightDocs?.hydrate();window.oversightExplore?.hydrate?.(id,tab);document.querySelectorAll('[data-nav]').forEach(a=>{const yes=a.dataset.nav===id;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(id==='library'){search();document.getElementById('chapter-search').addEventListener('input',e=>search(e.target.value));}document.title=({home:'House and Senate oversight',house:'House readiness',senate:'Senate investigative powers',topics:'Investigation topics',assurance:'Audit and review record',hiring:'Hiring plan',hub:'Central hub',states:'State enforcement',library:'The playbook',roadmap:'Build roadmap',contribute:'Research and reporting'}[id]||'Start')+' · Oversight Blueprint';window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{route();document.getElementById('main').focus({preventScroll:true});});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b?.dataset.action==='reporting')modal('<p class="eyebrow">SEPARATE SYSTEM · FUTURE GATE</p><h2>Confidential intake needs real protection.</h2><p>First establish a specialist source-protection platform, counsel and trained handlers, metadata minimization, retention and incident procedures, and independent security review.</p><p>This prototype has no confidential form, upload or identity collection.</p>');});
document.getElementById('close-dialog').addEventListener('click',()=>document.getElementById('info-dialog').close());
let deferredInstall;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
document.getElementById('install').addEventListener('click',async()=>{if(deferredInstall){await deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;}else modal('<p class="eyebrow">PHONE-READY PLAYBOOK</p><h2>Add to your home screen.</h2><p>On iPhone or iPad, open in Safari and choose Share → Add to Home Screen. On supported Android or desktop browsers, use the browser’s install menu when available.</p><p>Installation depends on browser and access settings. The offline shell contains public methods only. Live services require a network; document access follows its sharing settings.</p>');});
fetch('search.json').then(r=>{if(!r.ok)throw Error('index');return r.json();}).then(data=>{chapters=data;chapterState='loaded';search();}).catch(()=>{chapterState='error';search();});
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
route();

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('main').focus({preventScroll:false});});

window.addEventListener('documents-ready',()=>search());
